.ds-btn {
  --btn-fill: var(--card);
  --btn-text: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  min-height: 48px;
  padding: 0 1.4rem;
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  background: linear-gradient(var(--btn-fill), var(--btn-fill)) padding-box, var(--btn-stroke) border-box;
  color: var(--btn-text);
  font-family: var(--font-body);
  font-size: var(--text-body);
  font-weight: 560;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--dur-ui) var(--ease-out), color var(--dur-ui) var(--ease-out), transform var(--dur-ui) var(--ease-out);
}
.ds-btn svg { width: 1.05em; height: 1.05em; flex: none; transition: transform var(--dur-ui) var(--ease-out); }
.ds-btn:hover svg { transform: translate(2px, -1px); }
.ds-btn:active { transform: translateY(1px); }
.ds-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }

.ds-btn { --btn-fill: var(--accent); --btn-text: var(--accent-ink); }
.ds-btn:hover { --btn-fill: var(--accent-strong); }

