.ds-btn {
  --btn-fill: var(--btn-night-fill);
  --btn-text: var(--on-night);
  background: linear-gradient(var(--btn-fill), var(--btn-fill)) padding-box, var(--btn-stroke-night) border-box;
}
.ds-btn:hover { --btn-fill: var(--btn-night-fill-hover); }
.ds-btn:focus-visible { outline-color: var(--accent-night); }

.ds-btn-quiet {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 40px;
  margin-right: 0.5rem;
  padding: 0 0.85rem;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--font-body);
  font-size: var(--text-small);
  font-weight: 540;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out);
}
.ds-btn-quiet:hover { background: var(--paper-2); border-color: var(--ink-2); color: var(--ink); }
.ds-btn-quiet[aria-pressed="true"] { background: var(--ink); border-color: var(--ink); color: var(--on-night); }
.ds-btn-quiet[aria-pressed="true"]:hover { background: var(--ink); border-color: var(--ink); color: var(--on-night); }
.ds-btn-quiet:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }

.ds-field { display: grid; gap: 0.4rem; max-width: 22rem; font-family: var(--font-body); }
.ds-field-label { font-size: var(--text-small); font-weight: 560; color: var(--ink-2); }
.ds-input {
  width: 100%;
  min-height: 44px;
  padding: 0.55rem 0.85rem;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--card);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: var(--text-body);
  letter-spacing: -0.01em;
  transition: border-color var(--dur-fast) var(--ease-out);
}
.ds-input::placeholder { color: var(--muted); }
.ds-input:hover { border-color: var(--muted); }
.ds-input:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
}

.ds-nav { display: flex; gap: clamp(1rem, 2.6vw, 2.5rem); font-family: var(--font-body); }
.ds-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--ink-2);
  font-size: var(--text-label);
  font-weight: 560;
  text-transform: uppercase;
  text-decoration: none;
  transition: color var(--dur-fast) var(--ease-out);
}
.ds-nav-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 10px;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: right center;
  transition: transform var(--dur-ui) var(--ease-out);
}
.ds-nav-link:hover,
.ds-nav-link[aria-current="page"] { color: var(--ink); }
.ds-nav-link:hover::after,
.ds-nav-link[aria-current="page"]::after { transform: scaleX(1); transform-origin: left center; }
.ds-nav-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }

.ds-chip-row { display: flex; flex-wrap: wrap; gap: 0.5rem; align-items: center; font-family: var(--font-body); }
.ds-tag, .ds-chip {
  display: inline-flex;
  align-items: center;
  border-radius: var(--radius-pill);
  cursor: pointer;
}
.ds-tag {
  min-height: 24px;
  padding: 0 0.55rem;
  border: 1px solid var(--line-strong);
  background: transparent;
  color: var(--ink-2);
  font-size: var(--text-micro);
  font-weight: 560;
}
.ds-tag[data-source="aep_challenge"] { border-color: color-mix(in srgb, var(--accent) 45%, transparent); color: var(--accent-strong); }
.ds-tag[data-source="modeled"] { border-style: dashed; }
.ds-tag[data-source="scenario"] { border-style: dotted; border-width: 1.5px; }
.ds-tag[data-source="field_confirmed"] { border-color: var(--state-closed); color: var(--state-closed); }
.ds-tag:hover { border-color: var(--ink-2); }
.ds-tag[data-source="aep_challenge"]:hover { border-color: color-mix(in srgb, var(--accent) 45%, transparent); color: var(--accent-strong); }
.ds-tag[data-source="field_confirmed"]:hover { border-color: var(--state-closed); color: var(--state-closed); }
.ds-chip {
  min-height: 36px;
  padding: 0 0.9rem;
  border: 1px solid var(--line-strong);
  background: var(--card);
  color: var(--ink-2);
  font-size: var(--text-label);
  font-weight: 540;
}
.ds-chip[aria-pressed="true"] { border-color: var(--accent); background: var(--accent); color: var(--accent-ink); }
.ds-chip:hover:not(:disabled) { border-color: var(--ink-2); background: var(--paper-2); color: var(--ink-2); }
.ds-tag:focus-visible, .ds-chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.ds-state-row { display: flex; flex-wrap: wrap; gap: 0.5rem; font-family: var(--font-body); }
.ds-state {
  --state-ink: var(--state-unknown);
  --state-fill: var(--state-unknown-fill);
  --state-soft: var(--state-unknown-soft);
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 28px;
  padding: 0 0.7rem;
  border-radius: var(--radius-pill);
  background: var(--state-soft);
  color: var(--state-ink);
  font-size: var(--text-label);
  font-weight: 600;
}
.ds-state::before {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--state-fill);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--state-fill) 30%, transparent);
}
.ds-state[data-state="open"] { --state-ink: var(--state-open); --state-fill: var(--state-open-fill); --state-soft: var(--state-open-soft); }
.ds-state[data-state="closed"] { --state-ink: var(--state-closed); --state-fill: var(--state-closed-fill); --state-soft: var(--state-closed-soft); }
.ds-state[data-state="unknown"] { --state-ink: var(--state-unknown); --state-fill: var(--state-unknown-fill); --state-soft: var(--state-unknown-soft); }
.ds-state[data-state="critical"] { --state-ink: var(--state-critical); --state-fill: var(--state-critical-fill); --state-soft: var(--state-critical-soft); }
.ds-state:hover { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--state-ink) 35%, transparent); }
.ds-state:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.ds-card {
  max-width: 22rem;
  padding: var(--space-5);
  border: 1px solid var(--line);
  border-radius: var(--radius-xl);
  background: var(--card);
  color: var(--ink);
  box-shadow: var(--shadow-card);
  font-family: var(--font-body);
}
.ds-card-label { color: var(--muted); font-size: var(--text-micro); font-weight: 600; }
.ds-card-id { margin-top: 0.15rem; font-family: var(--font-mono); font-weight: 560; letter-spacing: -0.01em; }
.ds-card-copy { margin-top: 0.75rem; color: var(--ink-2); font-size: var(--text-small); line-height: 1.5; }
.ds-card:hover { border-color: var(--line-strong); }
.ds-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.ds-panel {
  max-width: 22rem;
  padding: var(--space-5);
  border-radius: var(--radius-xl);
  background: linear-gradient(180deg, var(--night-1) 0%, var(--night-panel) 100%);
  color: var(--on-night);
  font-family: var(--font-body);
}
.ds-panel-label { color: var(--on-night-muted); font-size: var(--text-micro); font-weight: 600; }
.ds-panel-id { margin-top: 0.15rem; font-family: var(--font-mono); letter-spacing: -0.01em; }
.ds-panel-copy { margin-top: 0.75rem; color: var(--on-night-muted); font-size: var(--text-small); line-height: 1.5; }
.ds-panel:hover { background: linear-gradient(180deg, var(--night-2) 0%, var(--night-panel) 100%); }
.ds-panel:focus-visible { outline: 2px solid var(--accent-night); outline-offset: 3px; }
